(* [comment removed for export] *)
Definition allocate_post (ra s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (sp gp tp : word) (F : bvmap 5 word) (fc : bv 32)
    (n AB b1 : Z) (ctx : word) (lo : Z) (m : mem) : machine_state -> Prop :=
  fun ms' => exists (t0' t1' t2' a1' a2' a3' a4' a5' a6' a7' t3' t4' t5' t6' : word) (m' : mem),
    ms' = MS (mkR ra (Z_to_bv 64 (bv_unsigned sp + 128)) gp tp t0' t1' t2' s0 s1 (Z_to_bv 64 (AB + rz_size n)) a1' a2' a3' a4' a5'
                  a6' a7' s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3' t4' t5' t6') F (ret_pc ra) fc None m' (seg_rom asegs)
    /\ munch [(AB, AB + 16); (AB + rz_size n + -16, AB + rz_size n + Z.min n 4096); (bv_unsigned sp - 32, bv_unsigned sp + 128)]%Z m m'
    /\ wmono asegs m m' /\ mem_inv asegs m'
    /\ rw_cells asegs m' (AB + rz_size n + -16) [C1 (Z_to_bv 8 2); C1 (Z_to_bv 8 (Z.land b1 243)); C2 (Z_to_bv 64 0); C4 (Z_to_bv 64 n); C8 ctx]
    /\ rw_cells asegs m' (AB + rz_size n) [CB (Z.to_nat (Z.min n 4096)) (repeat (Z_to_bv 8 190) (Z.to_nat (Z.min n 4096)))]
    /\ (16 < rz_size n -> rw_cells asegs m' AB [C8 (Z_to_bv 64 K_kAllocBegMagic); C8 (Z_to_bv 64 (AB + rz_size n + -16))])%Z
    /\ stk asegs m' lo (bv_unsigned sp + 128).

(* [comment removed for export] *)
Ltac p3b_hooks sp FR FRj ST :=
  do 3 zstep;
  lazymatch goal with |- evt _ _ (MS _ _ _ _ _ ?mm _) =>
    match goal with H : stk asegs mm _ _ |- _ => carve_frame 32%nat H end end;
  let MUz := fresh "MUz" in let WMz := fresh "WMz" in
  zidle_begin sp 32%Z MUz WMz; zstep; do 4 (zstep; fix_lit_store); zidle_end MUz WMz; do 3 zstep; do 2 zstep; do 3 zstep; ifT;
  do 5 zstep;
  lazymatch goal with |- evt _ _ (MS _ _ _ _ _ ?mm _) =>
    match goal with H : stk asegs mm _ _ |- _ =>
      match goal with FR0 : rw_cells asegs mm (bv_unsigned sp + -32)%Z _ |- _ => release_frame FR0 H (bv_unsigned sp) end end end;
  zstep;
  do 15 zstep;
  release_frame FRj ST (bv_unsigned sp + 8)%Z;
  release_frame FR ST (bv_unsigned sp + 128)%Z;
  zstep;
  finish.

(* [comment removed for export] *)
Lemma allocate_p3b_fill : forall sp gp ra0 t0 t1 t2 a1 a2v a3 a4 a5 a6 a7 t3 t4 t5 t6 s0v s6v s9v s3v
    fr0 fr1 fr2 fr3 fr4 fr5 fr6 fr7 fr8 fr9 fr10 fr11 fr12
    (F : bvmap 5 word) fc (m : mem) (n AB B T lo b1 : Z) (h0 uj lj j0 : list byte) (ctx : word),
  a2v = Z_to_bv 64 (Z.min n 4096) ->
  (1 <= n <= 2^31)%Z -> (kHighShadowEnd < AB)%Z -> (AB + needed2 n <= kHighMemEnd + 1)%Z -> (0 <= b1 < 256)%Z ->
